-- --------------------------------------------------------
-- Table structure for table `news`
DROP TABLE IF EXISTS `news`;
CREATE TABLE `news` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `title` varchar(255) COLLATE utf8_estonian_ci NOT NULL,
  `text` text COLLATE utf8_estonian_ci NOT NULL,
  `picture` longblob NOT NULL,
  `category_id` int(11) NOT NULL,
  `user_id` int(11) NOT NULL,
  PRIMARY KEY (`id`),
  KEY `category_id` (`category_id`),
  KEY `user_id` (`user_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_estonian_ci;
INSERT INTO `news` (`id`, `title`, `text`, `picture`, `category_id`, `user_id`) VALUES
(1, 'Mart Järvik ei ilmunud korruptsioonivastase erikomisjoni ette', 'Täna toimus korruptsioonivastane erikomisjon, mille ette kutsuti vastuseid andma maaeluminister Mart Järvik. Siiski ei ilmunud Järvik kohale.
Korruptsioonivastase erikomisjoni juht Katri Raik kinnitas, et Järvik ei ilmunud kohale, aga see-eest andis vastuseid ministri kantsler Illar Lemetti.

Eile küsisid opositsiooniliikmed peaminister Jüri Ratta käest, kas tal õnnestuks lubada minister Järvik valitsuse istungilt mõneks ajaks ära. Ratas kemples otsese vastuse andmisel, aga lõpuks nõustus, et ta soovitab Järvikul komisjoni ette ilmuda.

Minister pidi ilmuma komisjoni ette riigikogu kodu- ja töökorra seaduse kohaselt, mille kohaselt on komisjonil, ka erikomisjonil õigus nõuda valitsuse liikme osalemist komisjoni istungil.

Raik ütles, et erikomisjon jätkab esmaspäeval tööd. Lisaks erikomisjonile uurib Järviku küsimust Ratta kokku kutsutud uurimiskomisjon, mis peaks tulevaks nädalaks otsustama, kas Järvik on tööd pädevalt teinud.', , 1, 1),
(2, 'MHOMMIKUNE ERISAADE | Kas Helmed süüdistasid Kaja Kallast tõesti \"Mary Krossi tegemises\"? Kas Tommi Mäkinen maksab Eestis hiigelpalku?', '20. sünnipäeva nädala puhul tervitab Delfi viiel hommikul oma kasutajaid erisaate hommikuvaljaandega, vaadates otsa eelmise päeva, värske hommiku ja eelseisva päeva peamistele uudisteemadele. Täna olid hommikusaate stuudios Delfi peatoimetaja Karoliina Vasli, Ärilehe ajakirjanik Siiri Liiva ja Delfi tegevtoimetaja Tarmo Paju, peateemadeks Kaja Kallase vastu suunatud ähvardused, värske Ärilehe artikkel Eestis tegutsevast Tommi Mäkineni rallitiimist ja uued poliitreitingud. Eelseoleval laupäeval täitub Delfil 20. tegevusaasta.', , 1, 1),
(3, 'Politseikopter leidis rappa jõhvikaid korjama läinud mehe üles', 'Laupäeva õhtul sai häirekeskus teate, et Ida-Virumaal Alutaguse vallas Agusalu rabas on eksinud 67-aastane mees, kes oli läinud rappa jõhvikaid korjama ega suutnud enam iseseisvalt tagasiteed leida.

Otsingutesse kaasati politseikoer ja PPA lennusalga kopter. Kopteri meeskonnal õnnestus termokaamera abil mees rabast leida ning kopteripardale vintside abil tõsta. Mehe tervislik seisund oli hea ja ta anti üle kiirabile kontrolliks.', , 3, 1),
(4, 'Moskva lõksu langenud Lukašenka ei lase opositsiooni rihma lõdvemaks', 'Enne eilseid valimisi said kümned Valgevene opositsiooni esindajad teada, et ei saa kandideerida. Eile toimusid Valgevenes parlamendivalimised, mille kritiseerijad nimetab opositsioon 110-kohaist Valgevene parlamendi alamkoda kõigest kummitempliks, ametis olnud 1994. aastast saadik. Selle aja jooksul on Valgevenes toimunud valimisi kuulutanud ebaausateks, kirjutab uudisteagentuur AFP.', , 2, 1);

